const { google } = require('googleapis');
const fs = require('fs');
const path = require('path');

// Token path — generated by oauth flow
const TOKEN_PATH = path.join(__dirname, '../data/drive_token.json');
const CREDENTIALS_PATH = path.join(__dirname, '../data/drive_credentials.json');

function getAuthClient() {
  // Use service account or OAuth token stored locally
  if (fs.existsSync(TOKEN_PATH)) {
    const token = JSON.parse(fs.readFileSync(TOKEN_PATH));
    const auth = new google.auth.OAuth2();
    auth.setCredentials(token);
    return auth;
  }
  // Fallback: try service account
  if (fs.existsSync(CREDENTIALS_PATH)) {
    const creds = JSON.parse(fs.readFileSync(CREDENTIALS_PATH));
    if (creds.type === 'service_account') {
      return new google.auth.GoogleAuth({ credentials: creds, scopes: ['https://www.googleapis.com/auth/drive.readonly'] });
    }
  }
  throw new Error('No hay credenciales de Google Drive configuradas. Ver README.md');
}

async function listFiles(folderId) {
  const auth = getAuthClient();
  const drive = google.drive({ version: 'v3', auth });
  const res = await drive.files.list({
    q: `'${folderId}' in parents and mimeType='application/pdf' and trashed=false`,
    fields: 'files(id,name,size)',
    pageSize: 100
  });
  return res.data.files || [];
}

async function downloadPDF(fileId) {
  const auth = getAuthClient();
  const drive = google.drive({ version: 'v3', auth });
  const res = await drive.files.get({ fileId, alt: 'media' }, { responseType: 'arraybuffer' });
  return Buffer.from(res.data);
}

async function loadBrandManuals(folderId) {
  const pdfParse = require('pdf-parse');
  const files = await listFiles(folderId);
  
  let allContent = '';
  const loaded = [];

  for (const file of files) {
    try {
      // Skip very large files (>30MB) to avoid memory issues
      if (file.size && parseInt(file.size) > 30 * 1024 * 1024) {
        console.log(`⚠ Saltando ${file.name} (muy grande: ${Math.round(file.size/1024/1024)}MB)`);
        loaded.push({ name: file.name, status: 'skipped_large' });
        continue;
      }
      console.log(`📄 Cargando ${file.name}...`);
      const buf = await downloadPDF(file.id);
      const parsed = await pdfParse(buf, { max: 80 }); // max 80 pages
      allContent += `\n\n=== MANUAL: ${file.name} ===\n${parsed.text}`;
      loaded.push({ name: file.name, status: 'ok', pages: parsed.numpages, chars: parsed.text.length });
    } catch (e) {
      console.error(`✗ Error cargando ${file.name}: ${e.message}`);
      loaded.push({ name: file.name, status: 'error', error: e.message });
    }
  }

  return { content: allContent, files: loaded };
}

module.exports = { listFiles, loadBrandManuals };
